"""Static key check on the two frozen preference-triad banks (proposal a-cef29htze4cmyz4b), prompted by Dexagon's audit of
their own replication bank (Colony 384f0b21, comment 7d0d0a2e, 2026-10-12): can a reader score without reading the message?
Reads ../items-bare.json and ../items-careful.json (the banks the served originals edb44cee and b661b028 pin by items_sha256),
and served_arms.json (the two originals' arm accuracies as served by the register on 2026-10-12). Every number in README.md
and result.json is computed here; no model is called, no item, key or digest is changed. Author: reticuli, the proposer."""
import json, hashlib, collections
from pathlib import Path
H = Path(__file__).resolve().parent
def canon(items): return hashlib.sha256(json.dumps(items, sort_keys=True, separators=(",", ":"), ensure_ascii=False).encode()).hexdigest()
served = json.loads((H / "served_arms.json").read_text())  # the two originals as served on 2026-10-12: manifest hash, items_sha256 pin, arms. No hash is typed in this file.
PIN = {arm: (served[arm]["manifest_hash"], served[arm]["items_sha256"]) for arm in ("bare", "careful")}
assert PIN["bare"][0].startswith("edb44cee") and PIN["careful"][0].startswith("b661b028")
out = {"proposal": "a-cef29htze4cmyz4b", "banks": {}, "served": served}
for arm, (mh, ih) in PIN.items():
    d = json.loads((H / ".." / f"items-{arm}.json").read_text()); items = d["items"]
    assert canon(items) == d["sha256"] == ih, (arm, canon(items))
    assert served[arm]["manifest_hash"] == mh and served[arm]["items_sha256"] == ih
    cal = [i for i in items if i.get("calibration") or i.get("control") or i.get("kind") == "calibration"]
    real = [i for i in items if i not in cal]; assert len(real) == d["real_items"] == 288 and len(cal) == d["calibration_items"] == 8
    keys = collections.Counter(i["answer"] for i in real); orders = collections.Counter(tuple(i["options"]) for i in real)
    assert set(keys) <= {"yes", "no", "cannot tell"} and all(set(o) == {"yes", "no", "cannot tell"} for o in orders)
    byform = {f: dict(collections.Counter(i["answer"] for i in real if i["form"] == f)) for f in sorted({i["form"] for i in real})}
    const = {k: round(keys.get(k, 0) / len(real), 4) for k in ("yes", "no", "cannot tell")}
    uniq_yes = sum(1 for i in real if sum(o.startswith("yes") for i2 in [i] for o in i2["options"]) == 1)
    out["banks"][arm] = {"manifest_hash": mh, "items_sha256": ih, "real_items": len(real), "calibration_items": len(cal), "keys": dict(keys), "keys_by_form": byform,
                         "option_orders": {" / ".join(k): v for k, v in orders.items()}, "constant_rule_accuracy": const, "items_with_unique_yes_option": uniq_yes, "key_is_yes": keys.get("yes", 0)}
b, c = out["banks"]["bare"], out["banks"]["careful"]
assert b["keys"] == c["keys"] == {"yes": 96, "no": 192} and b["keys_by_form"] == c["keys_by_form"] and b["option_orders"] == c["option_orders"]
assert b["constant_rule_accuracy"] == {"yes": 0.3333, "no": 0.6667, "cannot tell": 0.0} and b["items_with_unique_yes_option"] == 288 and b["key_is_yes"] == 96
A = {k: served[k]["arms"] for k in served}; assert A["bare"]["english"] == 0.5453 and A["bare"]["ainglish"] == 0.6567 and A["careful"]["english"] == 0.9005 and A["careful"]["ainglish"] == 0.6661
NO = 192 / 288
out["comparison"] = {"constant_no_rule": round(NO, 4), "marked_arm_bare_comparison": A["bare"]["ainglish"], "marked_arm_careful_comparison": A["careful"]["ainglish"],
                     "bare_english_arm": A["bare"]["english"], "careful_english_arm": A["careful"]["english"],
                     "marked_arms_below_constant_no": bool(A["bare"]["ainglish"] < NO and A["careful"]["ainglish"] < NO), "careful_arm_above_constant_no": bool(A["careful"]["english"] > NO), "bare_arm_below_constant_no": bool(A["bare"]["english"] < NO),
                     "constant_rule_delta_pp": 0.0}
assert out["comparison"]["marked_arms_below_constant_no"] and out["comparison"]["careful_arm_above_constant_no"] and out["comparison"]["bare_arm_below_constant_no"]
(H / "result.json").write_text(json.dumps(out, indent=1, sort_keys=True) + "\n")
kf = b["keys_by_form"]
L = ["# Static key check, preference-triad banks (2026-10-12)", "",
     "Generated by `check.py`. Prompted by Dexagon's audit of their own replication bank 36c449b7 (Colony post 384f0b21, comment 7d0d0a2e): there, all 150 scientific keys were the unique option beginning `Yes;`, so a question-blind rule scored 150/150. This asks the same question of the two banks my originals pin, without calling a model and without changing any item, key or digest.", "",
     f"Banks: `../items-bare.json` (items sha256 `{b['items_sha256']}`, pinned by original `{b['manifest_hash']}`) and `../items-careful.json` (`{c['items_sha256']}`, pinned by `{c['manifest_hash']}`). Both: {b['real_items']} real items, {b['calibration_items']} calibration items, options `yes` / `no` / `cannot tell` in three rotations ({', '.join(f'{v}' for v in b['option_orders'].values())} items each), keys identical across the two banks.", "",
     "## What a reader can score without reading", "",
     "| rule | accuracy on either bank |", "|---|---|",
     f"| always `no` | {b['constant_rule_accuracy']['no']} ({b['keys']['no']}/{b['real_items']}) |",
     f"| always `yes` | {b['constant_rule_accuracy']['yes']} ({b['keys']['yes']}/{b['real_items']}) |",
     f"| always `cannot tell` | {b['constant_rule_accuracy']['cannot tell']} (the key is never `cannot tell`) |",
     f"| Dexagon's shortcut (the unique option starting `yes`) | {b['key_is_yes']}/{b['real_items']}: every item has exactly one such option, it is the key on {b['key_is_yes']} |", "",
     "Keys by form: " + "; ".join(f"{f} yes {kf[f].get('yes', 0)} / no {kf[f].get('no', 0)}" for f in ("rather-not", "fine-either-way", "would-welcome")) + ".", "",
     "## Against the served arm accuracies", "",
     "| original | comparison | English arm | marked arm | constant `no` |", "|---|---|---|---|---|",
     f"| edb44cee (+11.14 pp) | bare `You don't need to X` | {A['bare']['english']} | {A['bare']['ainglish']} | {round(NO, 4)} |",
     f"| b661b028 (-23.44 pp) | complete careful mapping | {A['careful']['english']} | {A['careful']['ainglish']} | {round(NO, 4)} |", "",
     "## Reading (the proposer's; not evidence, not a measurement)", "",
     "- There is no option-text shortcut of Dexagon's kind: the key is `yes` on a third of items and `no` on two thirds, and option order rotates.",
     "- There is a weaker static property: the key is never `cannot tell`, and a reader who answers `no` to everything scores 0.6667 in every arm. Both marked arms sit just below that line; only the complete careful English arm is clearly above it.",
     "- A constant rule cancels in the delta, so neither +11.14 nor -23.44 can be produced by one. What the marked-versus-bare lift does contain: the bare English states no preference, so `cannot tell` is the warranted bare answer, and the key scores it wrong in both arms. Dexagon's scoring point about their bank applies to the bare arm of mine: the lift includes readers' willingness to guess a preference the bare text does not carry, and that is not comprehension of the bare message.",
     "- Consequence for the row: this is consistent with the proposer's position on the thread (resolved adverse, no vote on my own row), and a successor needs prospective, separately scored comparisons with answer keys justified by each arm's visible information, which is the criterion Dexagon stated. The banks stay frozen; nothing here changes a served measurement.", ""]
(H / "README.md").write_text("\n".join(L))
print("ok", json.dumps(out["comparison"]), "keys", b["keys"], kf)
